1	// GVM 核心类的实现
2	
3	#include <cstdint>
4	#include <map>
5	#include <vector>
6	#include <memory>
7	#include <spdlog/logger.h>
8	
9	#include "gvmref_interface.h"
10	#include "gvm_global_var.hpp"
11	#include "gvm.hpp"
12	#include "gvm_structs.hpp"
13	#include <bitset>
14	#include <array>
15	#include "gvm_macro.h"
16	#include <string>
17	
18	//
19	// ------------------------- insn related ----------------------------------------
20	//
21	
22	bool gvm_t::isInsnCare(uint32_t insn, const std::vector<care_insn_t> care_insns) {
23	  // 判断指令是否 care
24	  for (const auto& pattern : care_insns) {
25	    if ((insn & pattern.mask) == pattern.value) {
26	      return true;
27	    }
28	  }
29	  return false;
30	}
31	
32	void gvm_t::disasm(uint32_t insn, char* insn_name) {
33	  std::vector<std::string> matched_names;
34	  for (const auto& pattern : disasm_table) {
35	    if ((insn & pattern.mask) == pattern.value) {
36	      matched_names.push_back(pattern.name);
37	    }
38	  }
39	  if (matched_names.empty()) {
40	    strcpy(insn_name, " ");
41	    return;
42	  }
43	  if (matched_names.size() > 1) {
44	    logger->error("GVM error: multiple disasm matches for insn 0x{:08x}: {}"
45	      , insn, fmt::join(matched_names, " "));
46	    assert(0);
47	  } else {
48	    strcpy(insn_name, matched_names[0].c_str());
49	  }
50	  return;
51	}
52	
53	//
54	// ------------------------- gvm_t::getDut() ----------------------------------------------
55	//
56	
57	static std::array<bool, 32> unpack_to_array(uint32_t v, size_t n) {
58	    std::bitset<32> bs(v);
59	    std::array<bool, 32> a{};
60	    for (size_t i = 0; i < n; ++i) {
61	        a[i] = bs[i]; // 保持一致：a[0] 对应最低位
62	    }
63	    return a;
64	}
65	
66	static std::string mask_to_string(const std::array<bool, 32>& mask, size_t n) {
67	    std::string s;
68	    for (size_t i = 0; i < n; ++i) {
69	        s.push_back(mask[i] ? '1' : '0');
70	    }
71	    return s;
72	}
73	
74	void gvm_t::getDut() {
75	  getDutWarpNew(); // 添加新 warp 条目
76	  getDutWarpFinish(); // 删除已完成 warp 条目
77	  getDutInsnDispatch(); // 添加新指令条目，其中不关心的指令直接置为 single_insn_cmp.cmp_pass = 1
78	  getDutInsnFinish(); // 标记指令条目为已完成，维护 dut_done 与 dut_result
79	  getDutXReg(); // 根据 warp 条目更新 XReg 条目
80	  getDutWarpNewSetRefXReg();
81	  clearGlobal(); // 清空全局变量
82	}
83	
84	void gvm_t::getDutWarpNew() {
85	  for (const auto& item : g_cta2warp_data) {
86	    dut_active_warp_t d;
87	    d.sm_id = item.sm_id;
88	    d.hardware_warp_id = item.hardware_warp_id;
89	    d.software_wg_id = item.software_wg_id;
90	    d.software_warp_id = item.software_warp_id;
91	    d.xreg_base = item.sgpr_base;
92	    d.xreg_usage = g_sgprUsage; // 临时特殊处理
93	    // d.vreg_base = item.vgpr_base;
94	    d.base_dispatch_id_set = 0;
95	    d.wg_slot_id_in_warp_sche = item.wg_slot_id_in_warp_sche;
96	    d.num_thread = item.num_thread_in_warp;
97	
98	    // check if the warp is already in the list
99	    bool found_sw = false;
100	    bool found_hw = false;
101	    for (const auto& warp : dut_active_warps) {
102	      if (warp.second.software_wg_id == d.software_wg_id && warp.second.software_warp_id == d.software_warp_id) {
103	        found_sw = true;
104	      }
105	      if (warp.second.sm_id == d.sm_id && warp.second.hardware_warp_id == d.hardware_warp_id) {
106	        found_hw = true;
107	      }
108	    }
109	    if (found_sw) {
110	      logger->error("GVM error: repeated cta2warp dispatch with same software_wg_id {} & software_warp_id {}.\n",
111	        d.software_wg_id, d.software_warp_id);
112	      assert(0);
113	    }
114	    if (found_hw) {
115	      logger->error("GVM error: repeated cta2warp dispatch with same sm_id {} & hardware_warp_id {}.\n",
116	        d.sm_id, d.hardware_warp_id);
117	      assert(0);
118	    }
119	    dut_active_warps[{d.software_wg_id, d.software_warp_id}] = d;
120	  }
121	}
122	
123	void gvm_t::getDutWarpFinish() {
124	  for (const auto& item : g_insn_dispatch_data) {
125	    if (item.insn == 0x0000400B) {
126	      // 0x0000400B 是 endprg 指令
127	      // delete dut_active_warp
128	      bool found_dut_active_warp = false;
129	      for (auto warp_it = dut_active_warps.begin(); warp_it != dut_active_warps.end();) {
130	        if (warp_it->second.sm_id == item.sm_id && warp_it->second.hardware_warp_id == item.hardware_warp_id) {
131	          if (found_dut_active_warp) {
132	            printf("GVM error in `gvm_t::getDutWarpFinish`: "
133	              "multiple items in `dut_active_warps` with same sm_id and hardware_warp_id\n");
134	            assert(0);
135	          }
136	          logger->debug(fmt::format("GVM info: endprg dispatched, deleting warp with sm_id: {}, hardware_warp_id: {}\n",
137	            warp_it->second.sm_id, warp_it->second.hardware_warp_id));
138	          warp_it = dut_active_warps.erase(warp_it);
139	          found_dut_active_warp = true;
140	        } else {
141	          ++warp_it;
142	        }
143	      }
144	      if (!found_dut_active_warp) {
145	        printf("GVM error in `gvm_t::getDutWarpFinish`: "
146	          "no item in `dut_active_warps` with required sm_id and hardware_warp_id\n");
147	        assert(0);
148	      }
149	      // 这里最好把对应的 ref warp 跑到头
150	    }
151	  }
152	}
153	
154	void gvm_t::getDutInsnDispatch() {
155	  for (const auto& item : g_insn_dispatch_data) {
156	    insn_t d;
157	    d.pc = item.pc;
158	    d.insn = item.insn;
159	    d.extended = item.is_extended;
160	    d.care = isInsnCare(item.insn, retire_care_insns);
161	    d.done = 0;
162	    d.retired = 0;
163	    d.single_insn_cmp.care = isInsnCare(item.insn, single_insn_cmp_care_insns);
164	    d.single_insn_cmp.dut_done = 0;
165	    d.single_insn_cmp.ref_done = 0;
166	    d.single_insn_cmp.cmp_pass = 0;
167	    if (!d.single_insn_cmp.care) {
168	      d.single_insn_cmp.cmp_pass = 1; // 不关心的指令直接置为比对通过
169	    }
170	    d.dispatch_id = item.dispatch_id;
171	
172	    bool found = false;
173	    for (auto& warp : dut_active_warps) {
174	      if (warp.second.sm_id == item.sm_id && warp.second.hardware_warp_id == item.hardware_warp_id) {
175	        if (found) {
176	          printf("GVM error in `gvm_t::getDutInsnDispatch`: "
177	            "multiple item in `dut_active_warps` with same sm_id and hardware_warp_id\n");
178	          assert(0);
179	        }
180	        assert(warp.second.insns.find(d.dispatch_id) == warp.second.insns.end()); // 错误：指令已被 dispatch 过一次
181	        warp.second.insns[d.dispatch_id] = d;
182	        found = true;
183	        if (!warp.second.base_dispatch_id_set) {
184	          // 设置本 warp 的首条指令的 dispatch_id
185	          warp.second.base_dispatch_id = d.dispatch_id;
186	          warp.second.base_dispatch_id_set = 1;
187	          warp.second.next_retire_dispatch_id = d.dispatch_id;
188	        }
189	      }
190	    }
191	    // 目前获取 warp 结束的标志是 endprg dispatch，
192	    // 但这距离 endprg 真正执行完成还有一段时间，
193	    // 在此期间仍有其他指令会 dispatch，但 dut_active_warps 中的 warp 已经被删除了
194	  }
195	}
196	
197	void gvm_t::getDutInsnFinish() {
198	  // 将 insns 中 care 的指令标记为已完成
199	  // 并记录 insn_t.single_insn_cmp 中 care 的指令的完成信息
200	  getDutXRegWbFinish();
201	  getDutVRegWbFinish();
202	  getDutBarDone();
203	}
204	void gvm_t::getDutXRegWbFinish() {
205	  for (const auto& item : g_xreg_wb_data) {
206	    if (!isInsnCare(item.insn, retire_care_insns)) {
207	      logger->error("GVM error in `gvm_t::getDutXRegWbFinish`: "
208	        "xreg writeback for instruction that does not care for retire\n"
209	        "getDutXRegWbFinish Error: sm_id: {}, hardware_warp_id: {}, dispatch_id: {}, pc: 0x{:08x}, insn: 0x{:08x}",
210	        item.sm_id, item.hardware_warp_id, item.dispatch_id, item.pc, item.insn);
211	    }
212	    assert(isInsnCare(item.insn, retire_care_insns));
213	    assert(!isInsnCare(item.insn, barrier_insns));
214	    assert(!isInsnCare(item.insn, single_insn_cmp_care_insns));
215	    bool found_warp = false;
216	    for (auto& warp : dut_active_warps) {
217	      if (warp.second.sm_id == item.sm_id && warp.second.hardware_warp_id == item.hardware_warp_id) {
218	        found_warp = true;
219	        auto insn_it = warp.second.insns.find(item.dispatch_id);
220	        if ((insn_it != warp.second.insns.end()) && (insn_it->second.done != 1)) {
221	          // 如果找到了该条指令，并且该指令尚未被标记为已完成
222	          assert(insn_it->second.pc == item.pc);
223	          assert(insn_it->second.insn == item.insn);
224	          assert(insn_it->second.care == true); // 标量寄存器写回指令需指导 retire
225	          // 维护 retire 相关变量
226	          insn_it->second.done = true;
227	          // 维护 single insn cmp 相关变量
228	          if (insn_it->second.single_insn_cmp.care == true) {
229	            insn_it->second.single_insn_cmp.dut_done = 1;
230	            insn_it->second.single_insn_cmp.dut_result.insn_type = InsnType::XREG;
231	            insn_it->second.single_insn_cmp.dut_result.xreg_result.rd = item.rd;
232	            insn_it->second.single_insn_cmp.dut_result.xreg_result.reg_idx = item.reg_idx;
233	          }
234	        } else {
235	          logger->debug(
236	              "GVM info in `gvm_t::getDutInsnFinish`: "
237	              "sm_id & hardware_warp_id match successful, but no item in this warp's unfinished "
238	              "dispatched insns with required dispatch_id"
239	          );
240	          logger->debug(
241	              "getDutInsnFinish info: sm_id: {}, hardware_warp_id: {}, dispatch_id: {}, pc: 0x{:08x}, insn: "
242	              "0x{:08x}",
243	              item.sm_id, item.hardware_warp_id, item.dispatch_id, item.pc, item.insn
244	          );
245	          // assert(0);
246	        }
247	      }
248	    }
249	    if (!found_warp) {
250	      // logger->error("GVM error in `gvm_t::getDutXRegWbFinish`: "
251	      //   "no warp in `dut_active_warps` with required sm_id and hardware_warp_id\n"
252	      //   "getDutXRegWbFinish Error: sm_id: {}, hardware_warp_id: {}, dispatch_id: {}, pc: 0x{:08x}, insn: 0x{:08x}",
253	      //   item.sm_id, item.hardware_warp_id, item.dispatch_id, item.pc, item.insn);
254	      // assert(0);
255	    }
256	  }
