311	void gvm_t::getDutBarDone() {
312	  for (const auto& item : g_bar_done_data) {
313	    assert(isInsnCare(item.insn, barrier_insns));
314	    if(isInsnCare(item.insn, single_insn_cmp_care_insns)){
315	      char buffer[128];
316	      disasm(item.insn, buffer);
317	      printf("%s\n", buffer);
318	      assert(0);
319	    } // barrier 指令不参与单指令比对
320	    assert(isInsnCare(item.insn, retire_care_insns)); // barrier 指令需指导 retire
321	    bool found = false;
322	    for (auto& warp: dut_active_warps) {
323	      if (warp.second.sm_id == item.sm_id && warp.second.wg_slot_id_in_warp_sche == item.wg_slot_id) {
324	        for (auto& insn: warp.second.insns) {
325	          if (insn.second.pc == item.pc) {
326	            if(insn.second.done == false) {
327	              found = true;
328	            }
329	            // 为什么这里不用 dispatch_id 来识别指令？因为各个 warp 的分支行为可能不同
330	            // 进而导致对同一条 barrier 指令的 dispatch_id 不同
331	            // 而这里拿到的 dispatch_id 只是最后一个完成的 warp 的 dispatch_id
332	            // 因此使用 pc 识别 barrier 指令
333	            // 激进地假设不会同时存在两个相同 pc 的未 retire 的 barrier 指令
334	            assert(insn.second.care == true); // barrier 指令需指导 retire
335	            insn.second.done = true; // 标记该指令已完成
336	          }
337	        }
338	      }
339	    }
340	    if(found == false) {
341	      logger->debug("GVM info in `gvm_t::getDutBarDone`: "
342	        "no insn in `dut_active_warps` with required unfinished barrier insn\n"
343	        "getDutBarDone info: sm_id: {}, wg_slot_id: {}, pc: 0x{:08x}, insn: 0x{:08x}",
344	        item.sm_id, item.wg_slot_id, item.pc, item.insn);
345	      // assert(0);
346	    }
347	  }
348	}
