373	void gvm_t::getDutWarpNewSetRefXReg() {
374	  // 这个函数是为了解决以下问题：
375	  // REF 对每一个 warp 的标量寄存器都是零初始化的；
376	  // 但 RTL DUT 的 CTA 调度器在向 SM 分派新 warp 时，只会在寄存器堆中分配一块空间，但不会零初始化；
377	  // 导致大量寄存器不匹配。
378	  // 因此这里在 DUT 的 CTA 调度器向 SM 分派新 warp 时，将 DUT 的该 warp 的寄存器数据同步到 REF 的对应 warp。
379	  for (const auto& item : g_cta2warp_data) {
380	    auto warp_it = dut_active_warps.find({ item.software_wg_id, item.software_warp_id });
381	    if (warp_it == dut_active_warps.end()) {
382	      logger->error("GVM error in `gvm_t::getDutWarpNewSetRefXReg`: "
383	        "no warp in `dut_active_warps` with required software_wg_id and software_warp_id\n"
384	        "getDutWarpNewSetRefXReg Error: software_wg_id: {}, software_warp_id: {}",
385	        item.software_wg_id, item.software_warp_id);
386	      assert(0);
387	    }
388	    auto &warp = warp_it->second;
389	
390	    gvmref_warp_xreg_t xreg_data;
391	    xreg_data.xreg.resize(warp.xreg_usage);
392	    for (uint32_t i = 0; i < warp.xreg_usage; ++i) {
393	      xreg_data.xreg[i] = warp.curr_xreg[i];
394	    }
395	    gvmref_set_warp_xreg(item.software_wg_id, item.software_warp_id, warp.xreg_usage, xreg_data);
396	  }
397	}
