414	int gvm_t::gvmStep() {
415	  checkRetire(); // 判断是否有 retire 指令，并将相关信息写入 retire_info
416	  stepRef(); // 根据 retire_info 步进 REF，每次步进前确认 PC，维护 ref_done 与 ref_result
417	  doSingleInsnCmp();
418	  doRetireCmp(); // 根据 retire_info 比对 DUT 和 REF 的特定 warp 的寄存器堆
419	  clearInsnItem(); // 删除已 retire 且已 single_insn_cmp 通过的指令条目
420	  resetRetireInfo(); // 重置 retire_info
421	  return 0;
422	}
