726	int gvm_t::doRetireCmp() {
727	  gvmref_xreg_t gvmref_xreg;
728	  for (const auto& item : retire_info.warp_retire_cnt) {    
729	  gvmref_get_xreg(&gvmref_xreg, item.software_wg_id, item.software_warp_id);
730	    auto& warp = dut_active_warps[{item.software_wg_id, item.software_warp_id}];
731	    for (int i=0; i<warp.xreg_usage; i++) {
732	      if (static_cast<uint32_t>(gvmref_xreg.xpr[i]) != warp.curr_xreg[i]) {
733	        logger->error(fmt::format(
734	          "GVM error: DUT and REF xreg mismatch at sm_id {}, hardware_warp_id {}, software_wg_id {}, software_warp_id {}, reg x{}: DUT = 0x{:08x}, REF = 0x{:08x}",
735	          warp.sm_id, warp.hardware_warp_id, warp.software_wg_id, warp.software_warp_id, i,
736	          warp.curr_xreg[i],
737	          static_cast<uint32_t>(gvmref_xreg.xpr[i])
738	        ));
739	      }
740	    }
741	  }
742	  return 0;
743	}
