745	void gvm_t::clearInsnItem() {
746	  for (auto& warp: dut_active_warps) {
747	    for (auto insn_it = warp.second.insns.begin(); insn_it != warp.second.insns.end(); ) {
748	      if ((insn_it->second.single_insn_cmp.cmp_pass != 0)
749	        && (insn_it->second.retired == true)) {
750	        insn_it = warp.second.insns.erase(insn_it);
751	      }
752	      else {
753	        break;
754	      }
