  // TBD
};

struct insn_result_t {
  InsnType insn_type;
  xreg_result_t xreg_result;
  vreg_result_t vreg_result;
};

struct single_insn_cmp_t {
  bool care; // 是否支持单指令比对功能。以 gvm_care_insns.cpp 中的列表为准
