  insn_result_t ref_result; // ref_done 为 true 时，其中的内容才有效
  int cmp_pass; // 0 for not compared yet, 1 for cmp pass, -1 for cmp fail, -2 for unknown insn type
};

struct insn_t {
  // dut_active_warp_t 中的 insns 中的条目
  uint32_t pc;
